 CREATE OR REPLACE FUNCTION public.letterheadapdxdtoj(p_intakenumber character varying, restitution_no integer, p_usersecurityid character varying)                                                                                                                                                                                                                                                                                                                                                                                                                                           
  RETURNS TABLE(youthname character varying, victim character varying, youth_parent character varying, youth_address character varying, victim_address character varying, county character varying, state_attorney_office character varying, restitution integer, amount_ordered numeric, due_date date, complaint_id character varying, petition_id character varying, hearing_date_time timestamp without time zone, court_ordered_date_time timestamp without time zone, case_mgmt_specialist character varying, phone_number character varying, restitution_coordinator character varying)
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
 declare                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
 restitution_number integer := restitution_no;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
 begin                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
         return QUERY select                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                 cast(yp.firstname || ' ' || yp.lastname as character varying) as youthname,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                 cast(vp.firstname || ' ' || vp.lastname as character varying) as victimname,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                 cast(ypp.firstname || ' ' || ypp.lastname as character varying) as youthparent,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                 cast(ypa.address || ' ' || ypa.city || ' ' || ypa.state || ' ' || ypa.zipcode as character varying ) as youth_address,                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                 cast(vpa.address || ' ' || vpa.city || ' ' || vpa.state || ' ' || vpa.zipcode as character varying ) as victim_address,                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                 cty.countyname as county,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                 st.statename as state_attorney_office,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                 restitution_number,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                 isr.payment,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                 isr.duedate,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                 isre.complaintid,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                 isrp.petitionid,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                 isrco.hearingdatetime,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                 isrco.courtorderdatetime,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                 up.fullname,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                 uph.phonenumber,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                 (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                 select                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                         fullname                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                 from                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                         userprofile                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                 where                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                         securityusersid = p_usersecurityid ) as Restitution_coordinator                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
         from                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
                 intakeservicerequest isrq                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
         left join intakeserreqrestitution isr on                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                 isr.intakenumber = isrq.intakenumber                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
         left join (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                 select                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                         p.personid,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                         p.firstname,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                         p.lastname,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                         activeflag                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
                 from                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                         person p)yp on                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                 yp.personid = isr.youthpersonid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                 and yp.activeflag = 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
         left join (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                 select                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                         p.personid,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                         p.firstname,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                         p.lastname,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                         activeflag                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
                 from                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                         person p)vp on                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                 vp.personid = isr.victimpersonid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                 and vp.activeflag = 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
         left join (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                 select                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                         p.personid,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                         p.firstname,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                         p.lastname,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                         activeflag                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
                 from                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                         person p)ypp on                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                 ypp.personid = isr.liablepersonid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                 and ypp.activeflag = 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
         left join (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                 select                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                         max(paymentnumber) "paymentnumber",                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                         intakeserreqrestitutionid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                 from                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                         intakeserreqrestitutionpayment                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                 group by                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
                         intakeserreqrestitutionid) isrpl on                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
                 isrpl.intakeserreqrestitutionid = isr.intakeserreqrestitutionid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
         left join intakeserreqrestitutionpayment irp on                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
                 irp.paymentnumber = isrpl.paymentnumber                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    
         left join intakeservicerequestpetition isrp on                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                 isrp.intakenumber = isrq.intakenumber                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
         left join personaddress ypa on                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                 yp.personid = ypa.personid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
         left join personaddress vpa on                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                 vp.personid = vpa.personid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
         left join intakeservicerequestcourtaction isrco on                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                 isrco.intakenumber = isrp.intakenumber                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
         left join intakeservicerequestevaluation isre on                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
                 isre.intakenumber = isrq.intakenumber                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
         left join routing ru on                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                 ru.servicerequestnumber = isrq.servicerequestnumber                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                 and ru.toroleid = 'JSCW'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
         left join userprofile up on                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                 up.securityusersid = ru.tosecurityusersid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
         left join userprofilephonenumber uph on                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                 uph.securityusersid = up.securityusersid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
         left join county cty on                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
                 cty.countyid = isr.countyid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
         left join state st on                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                 st.stateabbr = cty.state                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
         where                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                 isr.activeflag = 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
                 and isr.approvestatus = 'RSTAPR'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                 and isr.restitutionno = restitution_number                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
                 and isr.intakenumber = p_intakenumber                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
         order by                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                 isrco.updatedon                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
         limit 1;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
 end;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            
 $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   

